const topics = $input.first().json.body.topics || [];
if (!topics.length) throw new Error('в запросе нет списка topics');
return topics.map((t) => ({ json: { topic: String(t) } }));

const topic = $('Темы в элементы').item.json.topic;
const draft = $json.choices[0].message.content.trim();
return { json: { topic, draft } };

const topic = $('Черновик поста').item.json.topic;
let text = $json.choices[0].message.content.trim();
// страховка после двух ИИ-шагов: предложения с псевдостатистикой вырезаются кодом
const banned = /%|исследовани|по статистике|статистика показыва/i;
text = text
  .split(/\n+/)
  .map((p) => p.split(/(?<=[.!?])\s+/).filter((s) => !banned.test(s)).join(' '))
  .filter((p) => p.trim())
  .join('\n\n');
const slug = topic.toLowerCase().replace(/[^a-zа-яё0-9]+/gi, '-').replace(/^-|-$/g, '').slice(0, 60);
const md = `# ${topic}\n\n${text}\n`;
return { json: { topic, slug, chars: text.length }, binary: { data: { data: Buffer.from(md, 'utf-8').toString('base64'), mimeType: 'text/markdown', fileName: slug + '.md' } } };
